c img{width:100%;height:100%;object-fit:cover}.item-name{font-weight:600}.item-meta{font-size:12px;color:var(--muted);margin-top:4px}.item-price{text-align:right;font-weight:600}.shipment{background:#fbf5f1;border:1px solid var(--line);padding:15px;margin-top:12px}.shipment-summary{display:flex;justify-content:space-between;gap:12px;align-items:center}.tracking-id{font-size:12px;color:var(--muted);margin-top:4px}.timeline{border-left:2px solid var(--line);padding-left:18px;margin:18px 0 0 7px}.event{position:relative;padding-bottom:16px}.event:last-child{padding-bottom:0}.event:before{content:'';position:absolute;left:-24px;top:4px;width:9px;height:9px;background:var(--brown);border:3px solid #fbf5f1;border-radius:50%;box-shadow:0 0 0 1px var(--brown)}.event strong{text-transform:capitalize;font-size:13px}.event small,.event p{display:block;color:var(--muted);font-size:11px;margin:3px 0 0}.address{line-height:1.75;color:var(--muted)}.address strong{display:block;color:var(--ink);font-size:15px;margin-bottom:6px}.phone{margin-top:10px;color:var(--ink);font-weight:600}.line{display:flex;justify-content:space-between;gap:20px;padding:7px 0;color:var(--muted)}.line.total{border-top:1px solid var(--line);padding-top:14px;margin-top:7px;color:var(--ink);font-size:17px;font-weight:600}.payment-box{background:#f7eee9;padding:13px;margin-top:14px;font-size:12px}.cancelled-box{background:#f8e1df;color:#8e3733;padding:14px;line-height:1.5}.loading,.error{background:#fff;border:1px solid var(--line);padding:90px;text-align:center;color:var(--muted)}.modal-bg{display:none;position:fixed;inset:0;background:rgba(38,31,27,.55);z-index:100;place-items:center;padding:20px}.modal-bg.open{display:grid}.modal{width:min(470px,100%);background:var(--paper);padding:28px}.modal h2{font:600 25px 'Playfair Display',serif;margin:0}.modal p{color:var(--muted)}.modal textarea{width:100%;min-height:100px;border:1px solid var(--line);padding:12px;resize:vertical}.modal-actions{display:flex;justify-content:flex-end;gap:9px;margin-top:17px}.danger{border-color:#9b3e38!important;color:#9b3e38!important}.notice{display:none;color:#9b3e38;font-size:12px;margin-top:7px}
