<main class="detail-page wrap"><a class="back" href="{{ route('customer.orders') }}">← Back to my orders</a><div id="screen"><div class="loading">Loading complete order details…</div></div></main>
<div class="modal-bg" id="cancelModal"><div class="modal"><h2>Cancel this order?</h2><p>This action will cancel every package that has not entered processing.</p><textarea id="cancelReason" placeholder="Tell us why you want to cancel..."></textarea><div class="notice" id="cancelNotice"></div><div class="modal-actions"><button class="btn" onclick="closeCancel()">Keep order</button><button class="btn danger" onclick="cancelOrder()">Cancel order</button></div></div></div>
@endsection
@push('scripts')
<script>
if(protectPage()){
 const ORDER_ID=@json((int)$orderId),API_URL=`/api/customer/orders/${ORDER_ID}`;let order=null;const money=v=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(Number(v||0));const date=v=>v?new Intl.DateTimeFormat('en-IN',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):'—';const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));const label=v=>String(v||'').replaceAll('_',' ');const badge=v=>`<span class="status status-${v}">${label(v)}</span>`;
 function image(i){return i.image?`<img src="${esc(i.image)}" alt="">`:esc((i.product_name||'M')[0])}
 function timeline(s){if(!s)return '<div class="shipment"><strong>Preparing for dispatch</strong><div class="tracking-id">Tracking details will appear after pickup is requested.</div></div>';const events=s.tracking||[];return `<div class="shipment"><div class="shipment-summary"><div><strong>${esc(s.shipping_partner||'Delivery partner')}</strong><div class="tracking-id">Tracking: ${esc(s.tracking_number||'Awaiting AWB')}</div></div>${badge(s.status)}</div>${events.length?`<div class="timeline">${[...events].reverse().map(e=>`<div class="event"><strong>${label(e.status)}</strong><small>${esc(e.location||'Shipment update')} · ${date(e.tracked_at)}</small>${e.description?`<p>${esc(e.description)}</p>`:''}</div>`).join('')}</div>`:''}</div>`}
 function packageHtml(p){return `<section class="package"><div class="package-head"><div><div class="vendor">Sold & fulfilled by ${esc(p.vendor.name||'Meeta artisan')}</div><div class="package-no">Package ${esc(p.number)}</div></div>${badge(p.status)}</div>${p.cancellation_reason?`<div class="cancelled-box">Cancellation reason: ${esc(p.cancellation_reason)}</div>`:''}${p.items.map(i=>`<div class="item"><a class="pic" href="${i.product_slug?'/products/'+encodeURIComponent(i.product_slug):'#'}">${image(i)}</a><div><div class="item-name">${esc(i.product_name)}</div><div class="item-meta">${esc(i.variant_name||'Standard')} · SKU ${esc(i.sku||'—')} · Qty ${i.quantity}</div><div class="item-meta">${money(i.unit_price)} each</div></div><div class="item-price">${money(i.total)}</div></div>`).join('')}${timeline(p.shipment)}</section>`}
 function render(){const a=order.amounts,address=order.delivery_address,pay=order.payment;document.title=`${order.order_number} | MEETA`;document.getElementById('screen').innerHTML=`<div class="detail-head"><div><h1>Order ${esc(order.order_number)}</h1><p>Placed on ${date(order.placed_at)} · ${order.packages.length} package${order.packages.length===1?'':'s'}</p></div><div class="head-actions">${badge(order.order_status)}<button class="btn" onclick="loadOrder()">Refresh</button>${order.can_cancel?'<button class="btn danger" onclick="openCancel()">Cancel order</button>':''}</div></div>${order.cancellation_reason?`<div class="cancelled-box" style="margin-bottom:20px"><strong>Order cancelled</strong><br>${esc(order.cancellation_reason)}</div>`:''}<div class="grid"><div class="stack"><section class="panel"><div class="panel-title"><h2>Items & delivery</h2><span>${order.packages.reduce((s,p)=>s+p.items.reduce((n,i)=>n+i.quantity,0),0)} items</span></div>${order.packages.map(packageHtml).join('')}</section>${order.customer_note?`<section class="panel"><div class="panel-title"><h2>Order note</h2></div><div class="address">${esc(order.customer_note)}</div></section>`:''}</div><aside class="stack"><section class="panel"><div class="panel-title"><h2>Delivery address</h2></div><div class="address"><strong>${esc(address.full_name)}</strong>${[address.address_line_1,address.address_line_2,address.landmark,address.city,address.state,address.postal_code,address.country].filter(Boolean).map(esc).join('<br>')}<div class="phone">Phone: ${esc(address.phone)}</div></div></section><section class="panel"><div class="panel-title"><h2>Price details</h2></div><div class="line"><span>Item subtotal</span><span>${money(a.subtotal)}</span></div>${a.discount?`<div class="line"><span>Discount</span><span>−${money(a.discount)}</span></div>`:''}<div class="line"><span>Shipping</span><span>${a.shipping?money(a.shipping):'Free'}</span></div>${a.tax?`<div class="line"><span>Tax</span><span>${money(a.tax)}</span></div>`:''}<div class="line total"><span>Order total</span><span>${money(a.total)}</span></div>${pay?`<div class="payment-box"><strong>${esc(String(pay.method).toUpperCase())}</strong> · ${label(pay.status)}<br>Payment reference: ${esc(pay.payment_number)}</div>`:''}</section><section class="panel"><div class="panel-title"><h2>Need help?</h2></div><div class="address">For delivery or order questions, keep your order number ready when contacting support.</div></section></aside></div>`}
 async function loadOrder(){try{document.getElementById('screen').innerHTML='<div class="loading">Loading complete order details…</div>';order=(await api(API_URL)).data;render()}catch(e){document.getElementById('screen').innerHTML=`<div class="error"><h2>We could not open this order</h2><p>${esc(e.message)}</p><a class="btn" href="/orders">Back to orders</a></div>`}}
 function openCancel(){document.getElementById('cancelModal').classList.add('open')}function closeCancel(){document.getElementById('cancelModal').classList.remove('open');document.getElementById('cancelNotice').style.display='none'}
 async function cancelOrder(){const reason=document.getElementById('cancelReason').value.trim(),notice=document.getElementById('cancelNotice');if(reason.length<5){notice.textContent='Please provide at least 5 characters.';notice.style.display='block';return}try{await api(`${API_URL}/cancel`,{method:'POST',body:JSON.stringify({reason})});closeCancel();toast('Order cancelled successfully.');await loadOrder()}catch(e){notice.textContent=e.message;notice.style.display='block'}}
 document.getElementById('cancelModal').onclick=e=>{if(e.target.id==='cancelModal')closeCancel()};loadOrder();
}
</script>
@endpush
